% Fixture for fuzzyOptimizationProblem tests.

classdef fuzzyOptimizationFixture < matlab.unittest.fixtures.Fixture
    properties
        Examples
    end

    methods
        function setup(fixture)
            % K. Peeva and Z. Zahariev, max-product optimization example,
            % reproduced in Appendix A.6 of
            % https://doi.org/10.3390/info17030256.
            A = fuzzyMatrix([ ...
                0.0 0.2  0.05 0.0  0.4  0.0; ...
                0.1 0.6  0.3  0.0  0.2  0.2; ...
                0.8 0.48 0.24 0.48 0.0  0.0; ...
                0.3 0.0  0.0  0.4  0.8  0.15; ...
                0.0 0.0  0.12 0.2  0.48 0.1; ...
                0.5 0.3  0.0  0.1  0.6  0.0]);
            B = fuzzyMatrix([0.1; 0.3; 0.24; 0.2; 0.12; 0.15]);

            sys = fuzzySystem('maxprod', A, B);
            sys.full = true;
            sys.solve_inverse();

            z = [5 -4 8 2 -3 7];

            fixture.Examples{1} = struct( ...
                'object', z, ...
                'constraints', sys, ...
                'operation', 'minimize', ...
                'expected_solution', fuzzyMatrix([0; 0.5; 0; 0; 0.25; 0]), ...
                'expected_value', -2.75 ...
            );

            % Example 2: maximize with same system
            fixture.Examples{2} = struct( ...
                'object', z, ...
                'constraints', sys, ...
                'operation', 'maximize', ...
                'expected_solution', fuzzyMatrix([0.3; 0; 1; 0.5; 0.25; 1]), ...
                'expected_value', 16.75 ...
            );
        end
    end
end
